const query = $('Webhook').first().json.query ?? {};
const { personName, dateFrom, dateTo } = query;

// Map sheet rows → TimeEntry objects
// Column headers must exactly match: Date | Person Name | Task | Start Time | End Time | Total Time Spent | Task Count
let rows = items.map(item => ({
  json: {
    date:            String(item.json['Date'] ?? ''),
    personName:      String(item.json['Person Name'] ?? ''),
    taskName:        String(item.json['Task'] ?? ''),
    startTime:       String(item.json['Start Time'] ?? ''),
    endTime:         String(item.json['End Time'] ?? ''),
    durationSeconds: Number(item.json['Total Time Spent'] ?? 0),
    taskCount:       item.json['Task Count'] !== '' && item.json['Task Count'] != null
                       ? Number(item.json['Task Count'])
                       : null,
  }
})).filter(r => r.json.date !== '');

// Apply query filters
if (personName) rows = rows.filter(r => r.json.personName === personName);
if (dateFrom)   rows = rows.filter(r => r.json.date >= dateFrom);
if (dateTo)     rows = rows.filter(r => r.json.date <= dateTo);

// Sort newest first
rows.sort((a, b) => {
  if (b.json.date !== a.json.date) return b.json.date.localeCompare(a.json.date);
  return b.json.startTime.localeCompare(a.json.startTime);
});

return rows;
